INSERT INTO topics (code,name,description,is_active,sort_order,created_at,updated_at) VALUES ('CAREER','Công việc','Giới thiệu bản thân trong phỏng vấn cơ bản.',TRUE,6,UTC_TIMESTAMP(6),UTC_TIMESTAMP(6));
INSERT INTO scenarios (topic_id,code,title,description,learner_role,ai_role,communication_goal,context_description,ai_instruction,status,created_at,updated_at) SELECT id,'SELF_INTRODUCTION','Giới thiệu bản thân','Làm quen với một người bạn mới tại câu lạc bộ tiếng Anh.','Thành viên mới','Một thành viên thân thiện','Chào hỏi; giới thiệu tên giả, việc học hoặc công việc; hỏi lại ít nhất một câu.','Bạn đến buổi sinh hoạt đầu tiên của câu lạc bộ. Một thành viên tới làm quen. Có thể dùng thông tin hư cấu.','Act as a friendly club member welcoming a new member. Exchange introductions, discuss study or work and a shared interest; invite the learner to ask a question. Start the conversation in role and ask one question at a time. Use the server-selected A2 level with short common phrases or B1 with moderate detail. Keep the conversation in English. Give corrections in end-of-session feedback, not a running score. Do not claim to assess CEFR or pronunciation. Use invented details for practice.','ACTIVE',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6) FROM topics WHERE code='DAILY_LIFE';
INSERT INTO scenario_levels (scenario_id,level) SELECT id,'A2' FROM scenarios WHERE code='SELF_INTRODUCTION';
INSERT INTO scenario_levels (scenario_id,level) SELECT id,'B1' FROM scenarios WHERE code='SELF_INTRODUCTION';
INSERT INTO scenarios (topic_id,code,title,description,learner_role,ai_role,communication_goal,context_description,ai_instruction,status,created_at,updated_at) SELECT id,'STUDENT_DAY','Cuộc sống sinh viên','Trao đổi về lịch học và tìm thời gian học nhóm.','Sinh viên muốn học nhóm','Bạn cùng lớp','Nói về môn học, lịch rảnh; hỏi lịch của bạn; thống nhất thời gian và địa điểm học nhóm.','Sau giờ học, bạn trao đổi với bạn cùng lớp để sắp xếp một buổi học nhóm tại thư viện.','Act as a classmate planning a study session. Discuss classes and availability; agree a fictional study time and location without requesting a real timetable. Start the conversation in role and ask one question at a time. Use the server-selected A2 level with short common phrases or B1 with moderate detail. Keep the conversation in English. Give corrections in end-of-session feedback, not a running score. Do not claim to assess CEFR or pronunciation. Use invented details for practice.','ACTIVE',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6) FROM topics WHERE code='STUDENT_LIFE';
INSERT INTO scenario_levels (scenario_id,level) SELECT id,'A2' FROM scenarios WHERE code='STUDENT_DAY';
INSERT INTO scenario_levels (scenario_id,level) SELECT id,'B1' FROM scenarios WHERE code='STUDENT_DAY';
INSERT INTO scenarios (topic_id,code,title,description,learner_role,ai_role,communication_goal,context_description,ai_instruction,status,created_at,updated_at) SELECT id,'RESTAURANT_ORDER','Gọi món tại nhà hàng','Gọi món, hỏi thành phần và xác nhận đơn tại nhà hàng.','Khách hàng','Nhân viên phục vụ','Hỏi món hoặc thành phần; chọn đồ ăn và đồ uống; xác nhận đơn và hỏi tổng tiền.','Bạn đang ngồi tại một nhà hàng nhỏ. Có súp rau, cơm gà và mì rau cùng nước lọc hoặc trà. Giá chỉ là ví dụ hội thoại.','Act as a restaurant server. Offer the fictional menu: vegetable soup, chicken rice, vegetable noodles, water and tea. Help order and confirm items. Respect stated dietary needs; do not give medical assurances. Start the conversation in role and ask one question at a time. Use the server-selected A2 level with short common phrases or B1 with moderate detail. Keep the conversation in English. Give corrections in end-of-session feedback, not a running score. Do not claim to assess CEFR or pronunciation. Use invented details for practice.','ACTIVE',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6) FROM topics WHERE code='FOOD';
INSERT INTO scenario_levels (scenario_id,level) SELECT id,'A2' FROM scenarios WHERE code='RESTAURANT_ORDER';
INSERT INTO scenario_levels (scenario_id,level) SELECT id,'B1' FROM scenarios WHERE code='RESTAURANT_ORDER';
INSERT INTO scenarios (topic_id,code,title,description,learner_role,ai_role,communication_goal,context_description,ai_instruction,status,created_at,updated_at) SELECT id,'SHOPPING_CLOTHES','Mua sắm quần áo','Hỏi kích cỡ, màu sắc và giá một chiếc áo.','Người mua áo','Nhân viên cửa hàng','Hỏi kích cỡ, màu và giá; yêu cầu thử hoặc lựa chọn khác; quyết định mua hoặc từ chối lịch sự.','Bạn vào một cửa hàng để tìm áo cho một dịp cuối tuần. Cửa hàng có vài màu và kích cỡ; giá dùng để mô phỏng.','Act as a clothing shop assistant. Help find a shirt by size, colour and fictional price; offer an alternative and accept a polite refusal. Never request payment details. Start the conversation in role and ask one question at a time. Use the server-selected A2 level with short common phrases or B1 with moderate detail. Keep the conversation in English. Give corrections in end-of-session feedback, not a running score. Do not claim to assess CEFR or pronunciation. Use invented details for practice.','ACTIVE',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6) FROM topics WHERE code='SHOPPING';
INSERT INTO scenario_levels (scenario_id,level) SELECT id,'A2' FROM scenarios WHERE code='SHOPPING_CLOTHES';
INSERT INTO scenario_levels (scenario_id,level) SELECT id,'B1' FROM scenarios WHERE code='SHOPPING_CLOTHES';
INSERT INTO scenarios (topic_id,code,title,description,learner_role,ai_role,communication_goal,context_description,ai_instruction,status,created_at,updated_at) SELECT id,'ASK_DIRECTIONS','Hỏi đường','Tìm đường đi bộ tới thư viện trong một khu phố giả định.','Người cần hỏi đường','Người dân địa phương','Hỏi vị trí; hiểu trái/phải và mốc đường; hỏi lại để xác nhận hướng đi.','Trong khu phố giả định, thư viện ở sau công viên và gần quán cà phê. Bạn hỏi đường từ trạm xe buýt.','Act as a helpful local resident. Give consistent fictional walking directions from a bus stop to a library behind a park near a cafe. Use left/right and landmarks; invite clarification. Do not request live location. Start the conversation in role and ask one question at a time. Use the server-selected A2 level with short common phrases or B1 with moderate detail. Keep the conversation in English. Give corrections in end-of-session feedback, not a running score. Do not claim to assess CEFR or pronunciation. Use invented details for practice.','ACTIVE',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6) FROM topics WHERE code='TRAVEL';
INSERT INTO scenario_levels (scenario_id,level) SELECT id,'A2' FROM scenarios WHERE code='ASK_DIRECTIONS';
INSERT INTO scenario_levels (scenario_id,level) SELECT id,'B1' FROM scenarios WHERE code='ASK_DIRECTIONS';
INSERT INTO scenarios (topic_id,code,title,description,learner_role,ai_role,communication_goal,context_description,ai_instruction,status,created_at,updated_at) SELECT id,'HOTEL_BOOKING','Đặt phòng khách sạn','Hỏi phòng, tiện nghi và xác nhận yêu cầu đặt phòng giả định.','Khách muốn đặt phòng','Lễ tân khách sạn','Nêu ngày và số đêm giả định; hỏi loại phòng, giá, bữa sáng; xác nhận yêu cầu.','Bạn gọi một khách sạn để hỏi phòng cho chuyến đi giả định. Có phòng đơn và phòng đôi; mọi ngày, giá và thông tin khách là hư cấu.','Act as a hotel receptionist. Discuss fictional dates, nights, room types, price and breakfast; summarize a simulated reservation. Do not request real passport, address, card or contact information; do not imply a real booking. Start the conversation in role and ask one question at a time. Use the server-selected A2 level with short common phrases or B1 with moderate detail. Keep the conversation in English. Give corrections in end-of-session feedback, not a running score. Do not claim to assess CEFR or pronunciation. Use invented details for practice.','ACTIVE',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6) FROM topics WHERE code='TRAVEL';
INSERT INTO scenario_levels (scenario_id,level) SELECT id,'A2' FROM scenarios WHERE code='HOTEL_BOOKING';
INSERT INTO scenario_levels (scenario_id,level) SELECT id,'B1' FROM scenarios WHERE code='HOTEL_BOOKING';
INSERT INTO scenarios (topic_id,code,title,description,learner_role,ai_role,communication_goal,context_description,ai_instruction,status,created_at,updated_at) SELECT id,'WEEKEND_PLANS','Sở thích và cuối tuần','Trao đổi sở thích và lên một kế hoạch cuối tuần.','Người muốn rủ bạn đi chơi','Một người bạn','Nói hoạt động yêu thích; mời bạn; trao đổi lựa chọn và thống nhất thời gian giả định.','Bạn và một người bạn đang chọn giữa đi công viên, xem phim hoặc thăm bảo tàng vào cuối tuần.','Act as a friend discussing weekend plans. Ask about hobbies, compare a park visit, cinema or museum, and agree a fictional plan. Encourage a reason for the choice and handle disagreement politely. Start the conversation in role and ask one question at a time. Use the server-selected A2 level with short common phrases or B1 with moderate detail. Keep the conversation in English. Give corrections in end-of-session feedback, not a running score. Do not claim to assess CEFR or pronunciation. Use invented details for practice.','ACTIVE',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6) FROM topics WHERE code='DAILY_LIFE';
INSERT INTO scenario_levels (scenario_id,level) SELECT id,'A2' FROM scenarios WHERE code='WEEKEND_PLANS';
INSERT INTO scenario_levels (scenario_id,level) SELECT id,'B1' FROM scenarios WHERE code='WEEKEND_PLANS';
INSERT INTO scenarios (topic_id,code,title,description,learner_role,ai_role,communication_goal,context_description,ai_instruction,status,created_at,updated_at) SELECT id,'BASIC_INTERVIEW','Phỏng vấn cơ bản','Giới thiệu năng lực và động lực cho một công việc bán thời gian giả định.','Ứng viên','Người phỏng vấn','Giới thiệu bản thân; nêu một điểm mạnh hoặc ví dụ; trả lời lý do ứng tuyển và hỏi một câu về công việc.','Bạn tham gia phỏng vấn luyện tập cho vị trí trợ lý tại một cửa hàng sách giả định. Không cần kinh nghiệm thật hay CV cá nhân.','Act as an interviewer at a fictional bookshop. Ask basic questions for a part-time bookshop assistant: introduction, strength, a simple example and motivation. Let the candidate ask a question. Accept fictional or study-based examples; avoid sensitive personal questions and hiring guarantees. Start the conversation in role and ask one question at a time. Use the server-selected A2 level with short common phrases or B1 with moderate detail. Keep the conversation in English. Give corrections in end-of-session feedback, not a running score. Do not claim to assess CEFR or pronunciation. Use invented details for practice.','ACTIVE',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6) FROM topics WHERE code='CAREER';
INSERT INTO scenario_levels (scenario_id,level) SELECT id,'A2' FROM scenarios WHERE code='BASIC_INTERVIEW';
INSERT INTO scenario_levels (scenario_id,level) SELECT id,'B1' FROM scenarios WHERE code='BASIC_INTERVIEW';
